// fixtureQuota builds a quota cache with three F4s_v2-available regions
// (eastus2, westus2, westeurope) and one region whose SKU is restricted
// (centralus) so it must be filtered out.
func fixtureQuota() *quotacache.File {
	avail := quotacache.RegionData{
		Families: map[string]quotacache.FamilyQuota{
			"standardFSv2Family": {Limit: 100, CurrentValue: 0},
		},
		SKUs: map[string]bool{"Standard_F4s_v2": true},
	}
	restricted := quotacache.RegionData{
		Families: map[string]quotacache.FamilyQuota{
			"standardFSv2Family": {Limit: 100, CurrentValue: 0},
		},
		SKUs: map[string]bool{"Standard_F4s_v2": false},
	}
	return &quotacache.File{
		Regions: map[string]quotacache.RegionData{
			"eastus2":    avail,
			"westus2":    avail,
			"westeurope": avail,
			"centralus":  restricted,
		},
	}
}

// TestResolveRegionsAutoExpand locks in the `regions: []` contract: an empty
// requested list must expand to EVERY available region, not collapse to one.
// Regression guard for the panic where Run indexed Regions[0] on an empty slice.
func TestResolveRegionsAutoExpand(t *testing.T) {
	qc := fixtureQuota()

	got, err := resolveRegionsFromQuota(qc, "Standard_F4s_v2", nil, nil)
	if err != nil {
		t.Fatalf("resolveRegionsFromQuota: %v", err)
	}
	// All three available regions, in defaultCandidateRegions order; the
	// SKU-restricted centralus must be excluded.
	want := []string{"eastus2", "westus2", "westeurope"}
	if !equalStringSlice(got, want) {
		t.Errorf("auto-expand: got %v, want %v", got, want)
	}
}

// TestResolveRegionsExplicitIsCapped verifies a non-empty requested list is
// still capped at len(requested) (substituting unavailable regions only).
func TestResolveRegionsExplicitIsCapped(t *testing.T) {
	qc := fixtureQuota()

	got, err := resolveRegionsFromQuota(qc, "Standard_F4s_v2", []string{"westeurope"}, nil)
	if err != nil {
		t.Fatalf("resolveRegionsFromQuota: %v", err)
	}
	if len(got) != 1 || got[0] != "westeurope" {
		t.Errorf("explicit single region: got %v, want [westeurope]", got)
	}
}

// TestResolveRegionsEmptyWithoutCacheErrors ensures auto-expand without any
// cache fails fast (so Run never reaches Regions[0] on an empty slice).
func TestResolveRegionsEmptyWithoutCacheErrors(t *testing.T) {
	if _, err := resolveRegions(nil, nil, "Standard_F4s_v2", nil, nil); err == nil {
		t.Error("expected error for empty regions with no cache present")
	}
}

func TestWatchLoopExpiredDeadlineReturnsBeforePoll(test *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()
	profile := &config.AttackProfile{}
	spec := &runspec.RunSpec{StartAt: time.Now().Add(-4 * time.Minute)}
	err := watchLoop(ctx, nil, nil, profile, spec, "", nil, nil,
		&userconfig.File{}, nil, nil, "", "", "", "", nil)
	if err != nil {
		test.Fatalf("expired run should finish without waiting for a poll: %v", err)
	}
}

func TestWatchLoopPreservesCallerCancellation(test *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	profile := &config.AttackProfile{}
	spec := &runspec.RunSpec{StartAt: time.Now()}
	err := watchLoop(ctx, nil, nil, profile, spec, "", nil, nil,
		&userconfig.File{}, nil, nil, "", "", "", "", nil)
	if !errors.Is(err, context.Canceled) {
		test.Fatalf("got %v, want context cancellation", err)
	}
}

func TestNextVMSSCapacityDoesNotOverspendRemainder(test *testing.T) {
	remaining := 1
	for _, current := range []int{3, 3, 3} {
		next := nextVMSSCapacity(current, 1, remaining)
		remaining -= next - current
		if remaining < 0 {
			test.Fatal("scale-out exceeded the remaining fleet budget")
		}
	}
	if remaining != 0 {
		test.Fatalf("remaining = %d, want zero", remaining)
	}
	if next := nextVMSSCapacity(199, 5, 10); next != 200 {
		test.Fatalf("per-VMSS cap: got %d, want 200", next)
	}
}

func TestTotalCapacityIncludesUncertainDeployments(test *testing.T) {
	state := &watchState{
		capByVMSS:         map[string]int{"first": 4, "second": 4},
		uncertainCapacity: 3,
	}
	if total := state.totalCapacityLocked(); total != 11 {
		test.Fatalf("capacity = %d, want 11 including uncertain resources", total)
	}
}
